insert into public.questions (id, category, topic, difficulty, text_he, explanation_he, tags, template,
                              source_urls, verified_by, volatile, generator, obscurity, image)
select v ->> 'id', v ->> 'category', v ->> 'topic', (v ->> 'difficulty')::public.question_difficulty,
       v ->> 'text_he', v ->> 'explanation_he', v -> 'tags', v ->> 'template',
       array(select jsonb_array_elements_text(v -> 'source_urls')), v ->> 'verified_by', false,
       v ->> 'generator', (v ->> 'obscurity')::real, null
  from r
on conflict (id) do nothing;

